#!/usr/bin/env python3
"""Relatório rastreável das figuras já processadas por generate.py."""
import json
from pathlib import Path
import pandas as pd

OUT=Path(__file__).resolve().parents[1]
df=pd.read_csv(OUT/'processed/summary.csv').set_index('config')
manifest=json.loads((OUT/'manifest.json').read_text())
checks=json.loads((OUT/'validation/checks.json').read_text())
order=['L2','L6','L3','L7']
def f(k,col,d=2):return f"{df.loc[k,col]:.{d}f}"
specs=[
('A1','RPS nominal versus efetivo','P1, P8','A1_','`effective_config.json`; `request_log.csv`','RPS nominal = fontes × taxa/fonte; efetivo = inícios HTTP / 120 s','[30,150); coorte pelo início HTTP','Contagem de início dividida por 120 s','As taxas observadas ficaram próximas às nominais.','Uma realização por configuração; plano não equivale a início.'),
('A2','Evolução temporal do RPS','P1, P7','A2_','`request_log.csv`','Inícios HTTP por janela de 1 s','[0,150); principal sombreado','Bins semiabertos de 1 s','Há oscilações de segundo a segundo sem queda sustentada no recorte principal.','A contagem por bin não informa planejamento ou duração.'),
('B1','Utilização de CPU','P2, P3, P8','B1_','`victim_stats.jsonl`','`metrics.cpu_percent`: CPU Docker do contêiner `target_instance_1`; 100% ≈ um núcleo lógico','[30,150)','Amostras reais; caixa, mediana, média e extremos','As médias amostradas foram maiores em 32 RPS.','Sem ponderação temporal nem intervalo de confiança; amostras autocorrelacionadas.'),
('B2','Evolução temporal da CPU','P2, P7','B2_','`victim_stats.jsonl`','CPU Docker da vítima (%)','[0,150); principal sombreado','Timestamps monotônicos reais; linhas ligam amostras','L3 e L7 exibem níveis e oscilações de CPU superiores aos de L2 e L6.','Amostragem de cerca de 3 s; os trechos entre pontos não são observações.'),
('B3','Utilização de memória','P6','B3_','`victim_stats.jsonl`','`raw_mem_usage` / 2²⁰: MiB do contêiner da vítima','[30,150)','Amostras reais; caixa, mediana, média e extremos','As médias foram próximas, com valores um pouco maiores em 32 RPS.','Inclui memória do contêiner, não RAM do host nem RSS isolado do Python.'),
('B4','Evolução temporal da memória','P6, P7','B4_','`victim_stats.jsonl`','`raw_mem_usage` / 2²⁰ em MiB','[0,150); principal sombreado','Timestamps monotônicos reais','Há aumento líquido entre a primeira e última amostra nas quatro execuções.','Eixo vertical ampliado para mostrar mudanças de poucos MiB; as séries não explicam alocação ou liberação internas.'),
('C1','Ocupação dos workers','P4, P7','C1_','`diagnostics/victim/events.jsonl`','Operações entre `work_started_at` e `work_finished_at`','[0,150); frações em [30,150)','Reconstrução retrospectiva orientada a eventos','Dois workers ocupados ocorreram em todas as execuções, mais tempo em L3/L7.','Não representa handlers HTTP ativos; oscilações rápidas se adensam visualmente.'),
('C2','Operações computacionais pendentes','P4, P7','C2_','`diagnostics/victim/events.jsonl`','Aguardando = submetida e ainda não iniciada; em execução = iniciada e ainda não concluída','[0,150); máximos do recorte completo','Reconstrução orientada a eventos','Picos de aguardando: L2 4, L6 3, L3 9, L7 12.','Não é a profundidade interna exata do executor.'),
('C3','Espera por worker','P4, P8','C3_','`diagnostics/victim/events.jsonl`; `request_log.csv`','`(work_started_at − work_submitted_at) × 1000` ms','Coorte de início HTTP [30,150)','Boxplot p5–p95, ECDF e tabela','O p95 foi maior em L3/L7, especialmente L7.','Inclui IPC e escalonamento; não corresponde à espera HTTP total.'),
('C4','Acúmulo e espera','P4','C4_','`diagnostics/victim/events.jsonl`; `request_log.csv`','Operações aguardando imediatamente antes da submissão versus espera subsequente da mesma operação','Coorte de início HTTP [30,150)','Dispersão individual; estado antes do evento corrente','Em L7, esperas longas coincidiram com maiores quantidades aguardando.','Associação descritiva; sobreposição de pontos e sem identificação causal.'),
('D1','Distribuição da duração HTTP','P5, P8','D1_','`request_log.csv`; `rtt_log.csv` para conferência','`duration_ms` no cliente; somente respostas HTTP 2xx','Coorte de início HTTP [30,150)','Boxplot p5–p95 e ECDF','Duração média e p95 foram maiores em 32 RPS; L7 teve a cauda mais longa.','Inclui rede, espera e processamento; não mede só tempo de serviço.'),
('D2','Duração HTTP ao longo do tempo','P5, P7','D2_','`request_log.csv`','Mediana e p95 de `duration_ms` de respostas HTTP 2xx','Início HTTP em bins de 10 s em [0,150)','p95 apenas com n≥20 por bin; contagens em `processed/http_10s_*.csv`','L7 teve um episódio de maior p95 por volta de 50–80 s.','Valores por janela descrevem esta execução; linha entre bins não é dado medido.'),
('D4','Respostas, erros e timeouts','P1, P8','D4_','`request_log.csv`','Desfecho por `outcome`, `http_status`, `error_type`; denominador = inícios em [30,150)','Coorte de início HTTP [30,150)','Contagens e proporções por configuração','Todas as tentativas da coorte tiveram resposta HTTP 200.','Conclusões podem ocorrer após o limite da coorte; nenhum timeout foi confundido com resposta.'),
('E1','Painel temporal completo','P1–P8','E1_','`request_log.csv`; `victim_stats.jsonl`; eventos da vítima','Seis faixas: inícios/s, CPU, memória, workers ocupados, operações aguardando, duração HTTP','[0,150); principal sombreado','Bins de 1 s e 10 s, amostras reais e estados por evento','L7 reúne maior CPU, mais acúmulo e episódio de duração elevada.','Painel alinha relógios; resolução e significado diferem por faixa.'),
('E2','Matrizes comparativas','P2, P3, P7, P8','E2_','Mesmos registros das famílias A–D','Seis métricas em matriz: linhas 2/4 fontes; colunas 16/32 RPS','[0,150); principal sombreado','Escala vertical comum por métrica','Comparações entre colunas evidenciam maiores recursos e duração em 32 RPS.','Uma realização por célula; diferenças não são efeitos causais.'),
]

lines=['# Relatório das visualizações legítimas A1','',
'## Delimitação e auditoria','',
'Somente a caracterização de 06/11/2026 em `experiment_results/legitimate-characterization-a1-20261106T202205Z/` foi processada. `raw/effective_config.json` e `raw/run_status.json` confirmam L2 (2×8), L6 (4×4), L3 (2×16), L7 (4×8), `/medium`, 150 s, topologia direta, uma vítima, dois workers, concorrência legítima agregada 64 e ausência de ataque. `report.md` da A1 confirma o intervalo principal [30,150); a análise o aplica como intervalo semiaberto relativo ao início monotônico efetivo do status. Há uma execução por célula. O inventário anterior foi consultado apenas para localização.', '',
'Os timestamps HTTP de `request_log.csv` trazem época e `elapsed_seconds` relativo à execução. CPU e memória usam `monotonic` de `victim_stats.jsonl` menos `experiment_start_monotonic`. Os registros da vítima trazem `work_submitted_at`, `work_started_at` e `work_finished_at` dentro de `handler_finished`; os workers declararam `CLOCK_MONOTONIC` no mesmo namespace. Assim, a reconstrução é retrospectiva, por operação, e as séries são alinháveis. Registros `capture_audit` anteriores à execução foram excluídos. Planejamento, submissão e início HTTP dos geradores constam dos eventos `planned`, `submitted`, `task_started` e `http_started`, mas as taxas desta análise usam o início de `request_log.csv`. Entrada no handler é outro evento; conclusão HTTP é `end_elapsed_seconds`, posterior ao início. A fila HTTP pré-handler não foi medida diretamente.', '',
'As quatro execuções terminaram `completed/simulation_end`, com `producers_drained=true` e `errors=[]`. Há `request_log.csv`, `rtt_log.csv`, `victim_stats.jsonl`, `simulation_metrics.csv`, eventos da vítima, eventos e journals das fontes, `console.log`, relatórios individuais e análise comparativa A1. `rtt_log.csv` tem os mesmos IDs e totais do log HTTP; `simulation_metrics.csv` é uma série de ticks mais esparsa e não alimenta as figuras de recursos. `normal_traffic_summary_log.csv` registra a configuração e o resumo das fontes. Não foram encontrados erros ou timeouts HTTP nas quatro execuções. O `run_status.json` confirma encerramento normal, e a verificação dos eventos confirma ciclos computacionais completos.', '',
'### Síntese numérica do intervalo principal','',
'| Configuração | Inícios / RPS | CPU média / mediana / máximo (%) | Memória média / mediana / máximo (MiB) | Espera mediana / p95 / máximo (ms) | HTTP mediana / média / p95 / máximo (ms) |',
'|---|---:|---:|---:|---:|---:|']
for k in order:
    lines.append(f'| {k} | {int(df.loc[k,"http_started"])} / {f(k,"effective_rps",3)} | {f(k,"cpu_mean",1)} / {f(k,"cpu_median",1)} / {f(k,"cpu_max",1)} | {f(k,"mem_mean_mib",2)} / {f(k,"mem_median_mib",2)} / {f(k,"mem_max_mib",2)} | {f(k,"worker_wait_median_ms",2)} / {f(k,"worker_wait_p95_ms",2)} / {f(k,"worker_wait_max_ms",1)} | {f(k,"http_median_ms",2)} / {f(k,"http_mean_ms",2)} / {f(k,"http_p95_ms",2)} / {f(k,"http_max_ms",1)} |')
lines += ['', 'CPU e memória têm 40 observações no principal em L2/L6/L3 e 41 em L7. Espera e duração têm respectivamente 1912, 1930, 3766 e 3819 operações/respostas válidas; zero ciclos faltantes. CPU Docker pode exceder 100%. A cadência bruta de CPU/memória teve mediana aproximada de 3,015 s, apesar do polling configurado em 1 s. A memória mudou entre primeira e última amostra em +0,79, +0,78, +3,62 e +2,31 MiB para L2, L6, L3 e L7. A comparação inicial/final é uma diferença entre duas observações, não uma tendência estimada.', '',
'## Catálogo comentado','']
for code,name,question,prefix,source,definition,interval,aggregation,obs,limit in specs:
    files=[x for x in manifest['figures'] if Path(x).stem.startswith(prefix) and x.endswith('.png')]
    links=', '.join(f'[{Path(x).name}]({x})' for x in files)
    lines += [f'### {code} — {name}','',f'**Pergunta:** {question}. **Arquivos PNG:** {links}. Cada PNG tem PDF vetorial homônimo.','',f'**Fonte:** {source}. **Métrica:** {definition}. **Intervalo:** {interval}. **Agregação:** {aggregation}.','',f'**Observação:** {obs} **Limitação/qualidade:** {limit}','']
lines += ['## Comparações descritivas','',
f'- **L2 → L3, duas fontes:** RPS {f("L2","effective_rps",3)} → {f("L3","effective_rps",3)}; CPU média {f("L2","cpu_mean",1)}% → {f("L3","cpu_mean",1)}%; HTTP médio {f("L2","http_mean_ms",1)} → {f("L3","http_mean_ms",1)} ms; espera p95 {f("L2","worker_wait_p95_ms",1)} → {f("L3","worker_wait_p95_ms",1)} ms.',
f'- **L6 → L7, quatro fontes:** RPS {f("L6","effective_rps",3)} → {f("L7","effective_rps",3)}; CPU média {f("L6","cpu_mean",1)}% → {f("L7","cpu_mean",1)}%; HTTP médio {f("L6","http_mean_ms",1)} → {f("L7","http_mean_ms",1)} ms; espera p95 {f("L6","worker_wait_p95_ms",1)} → {f("L7","worker_wait_p95_ms",1)} ms.',
f'- **L2 → L6, 16 RPS:** RPS {f("L2","effective_rps",3)} → {f("L6","effective_rps",3)}; CPU média {f("L2","cpu_mean",1)}% → {f("L6","cpu_mean",1)}%; HTTP médio {f("L2","http_mean_ms",1)} → {f("L6","http_mean_ms",1)} ms; espera p95 {f("L2","worker_wait_p95_ms",1)} → {f("L6","worker_wait_p95_ms",1)} ms.',
f'- **L3 → L7, 32 RPS:** RPS {f("L3","effective_rps",3)} → {f("L7","effective_rps",3)}; CPU média {f("L3","cpu_mean",1)}% → {f("L7","cpu_mean",1)}%; HTTP médio {f("L3","http_mean_ms",1)} → {f("L7","http_mean_ms",1)} ms; espera p95 {f("L3","worker_wait_p95_ms",1)} → {f("L7","worker_wait_p95_ms",1)} ms.', '',
'L2 sustentou aproximadamente 16 RPS, teve respostas integrais, CPU média amostrada abaixo das configurações de 32 RPS e pico de quatro operações aguardando. Esses registros tornam a escolha de L2 como referência operacionalmente compreensível nesta execução. L6 também sustentou 16 RPS e apresentou algumas medidas de latência menores; os dados não estabelecem superioridade estatística de L2. As diferenças entre células são observações de realizações únicas, sem inferência causal ou testes de significância.', '',
'## Validação e limites','',
f'- {checks["figure_pairs"]} figuras, cada uma em PNG de 300 dpi e PDF vetorial. Fontes, identificadores, eixos, unidades e sobreposições foram inspecionados nas figuras de distribuição, desfechos, matriz CPU, dispersão C4 e painel E1.',
'- Contagens de `request_log.csv`, `rtt_log.csv`, inícios e fins HTTP nas fontes e ciclos da vítima coincidem por execução. IDs de requisição são únicos. Durações são não negativas e coerentes com os timestamps de início/fim.',
'- A reconstrução não produziu estados negativos nem mais de dois workers em execução. Eventos simultâneos seguem a ordem submissão, início e fim; os ciclos têm instantes estritamente ordenados. Frações de ocupação em [30,150) somam 1.',
'- Os hashes SHA-256 das entradas utilizadas estão em `validation/checks.json`; o gerador somente lê as entradas. O comando de reprodução abaixo pode confirmar a persistência desses hashes após execução.',
'- Não houve imputação de CPU ou memória nem interpolação de pontos ausentes. As linhas entre amostras servem somente à leitura visual. As séries de estados por evento podem formar áreas visualmente densas.',
'- Limites: não há medição direta da fila pré-handler; espera por worker inclui IPC/escalonamento; operações aguardando não são profundidade privada do executor; duração HTTP do cliente abrange mais do que serviço; não separamos causas das diferenças; nenhuma figura obrigatória foi omitida.', '',
'## Reprodução','',
'Na raiz do repositório, com Python 3, `numpy`, `pandas` e `matplotlib`:', '',
'```bash','python3 reports/a1_visual_characterization_20261112/scripts/generate.py','python3 reports/a1_visual_characterization_20261112/scripts/write_report.py','```','',
'Entradas: exclusivamente a pasta A1 acima. Parâmetros: 150 s, principal [30,150), RPS em 1 s, duração em 10 s com p95 somente para n≥20. Saídas: `figures/`, `processed/`, `manifest.json`, `validation/checks.json` e este relatório. Código: scripts locais desta entrega; proveniência da coleta em `raw/run_provenance.json` de cada configuração.', '',
'Versão dos scripts (SHA-256): `generate.py` '+__import__('hashlib').sha256((OUT/'scripts/generate.py').read_bytes()).hexdigest()+'; `write_report.py` '+__import__('hashlib').sha256(Path(__file__).read_bytes()).hexdigest()+'.', '']
(OUT/'relatorio.md').write_text('\n'.join(lines),encoding='utf-8')
(OUT/'README.md').write_text('# Visualizações A1\n\nConjunto exploratório de 53 figuras em PNG/PDF. Consulte [relatorio.md](relatorio.md), [manifest.json](manifest.json) e [validation/checks.json](validation/checks.json).\n\nReprodução na raiz do repositório:\n\n```bash\npython3 reports/a1_visual_characterization_20261112/scripts/generate.py\npython3 reports/a1_visual_characterization_20261112/scripts/write_report.py\n```\n\nDependências: Python 3, numpy, pandas, matplotlib.\n',encoding='utf-8')
